import importlib.util
import sys
from pathlib import Path


def load(rel):
    path = Path(__file__).parent / rel
    sys.path.insert(0, str(path.parent))
    spec = importlib.util.spec_from_file_location("under_test", path)
    module = importlib.util.module_from_spec(spec)
    sys.modules["under_test"] = module
    spec.loader.exec_module(module)
    return module

m = load('evals/swe_tasks.py')

def test_fix():
    r=m.parse({'gold_sources':{'a.py':'x'},'gold_files':['a.py']}); assert r=={'gold_sources':{'a.py':'x'},'gold_files':['a.py']}

def test_regression():
